    "runner_results": null
   }
  ],
  "shared_queue": [],
  "instrument_queue": [
   "AUTHOR: validation control for instrument endpoint-1-readout vv1: held-out ground truth for \"Anchor: contact overlap with 6IHB at 4.5 Angstrom, or interface backbone RMSD\"",
   "AUTHOR: validation control for instrument endpoint-2-readout vv1: held-out ground truth for \"Input 1: mean af2_h_per_run over 9 timing runs\"",
   "AUTHOR: validation control for instrument endpoint-3-readout vv1: held-out ground truth for \"Input 2: median md_ns_per_day_a100 over 3 complexes\"",
   "AUTHOR: validation control for instrument endpoint-4-readout vv1: held-out ground truth for \"Input 3: mean aux_h_per_pair over 3 pairs\"",
   "AUTHOR: validation control for instrument endpoint-5-readout vv1: held-out ground truth for \"Input 4: n_storage_gib extrapolated to the 216-run grid\"",
   "AUTHOR: validation control for instrument endpoint-6-readout vv1: held-out ground truth for \"Harness validity: planted 60 s sleep error, and seed-to-seed spread of timings\"",
   "AUTHOR: validation control for instrument endpoint-7-readout vv1: held-out ground truth for \"Cost and time\""
  ],
  "authored": null
 },
 "gate": "BUDGET_AND_DESIGN_APPROVAL: human commits a gate file answering, of record, every diff question, every non-reproducing grounding note, and every queued item (instrument validations included; \"accepted as-is\" is an answer) before mode=build."
}

